/** One persistent payout readout and shared coin/luckbox spot for the reveal. */
export function createDgnWinnings(doc) {
  const view = doc.defaultView || globalThis.window || globalThis;
  const el = (tag, className, text) => {
    const node = doc.createElement(tag); node.className = className;
    if (text != null) node.textContent = text;
    return node;
  };
  const element = el('section', 'dgn-winnings');
  element.setAttribute('aria-label', 'Degenerette winnings');
  const rewardSlot = el('div', 'dgn-winnings__reward');
  const coinSlot = el('div', 'dgn-winnings__coin');
  const rewardLabel = el('span', 'dgn-winnings__reward-label', 'REWARD');
  const lootboxButton = el('button', 'dgn-winnings__lootbox');
  lootboxButton.type = 'button'; lootboxButton.hidden = true; lootboxButton.disabled = true;
  const lootboxArt = el('img', 'dgn-winnings__lootbox-art');
  lootboxArt.alt = ''; lootboxArt.decoding = 'async';
  const lootboxLabel = el('span', 'dgn-winnings__reward-label', 'LUCKBOX');
  lootboxButton.appendChild(lootboxArt); lootboxButton.appendChild(lootboxLabel);
  const placeholder = el('img', 'dgn-winnings__placeholder');
  placeholder.src = '/whitepaper/flame-center.svg'; placeholder.alt = '';
  const label = el('span', 'dgn-winnings__label', 'WINNINGS');
  const amount = el('div', 'dgn-winnings__amount');
  const primary = el('strong', 'dgn-winnings__value', '0');
  const secondary = el('span', 'dgn-winnings__secondary');
  const status = el('span', 'dgn-winnings__status');
  const announcement = el('span', 'dgn-winnings__announcement');
  announcement.setAttribute('role', 'status');
  announcement.setAttribute('aria-live', 'polite');
  amount.setAttribute('aria-hidden', 'true');
  amount.appendChild(primary); amount.appendChild(secondary);
  coinSlot.appendChild(placeholder);
  for (const node of [coinSlot, rewardLabel, lootboxButton]) rewardSlot.appendChild(node);
  for (const node of [rewardSlot, label, amount, status, announcement]) element.appendChild(node);
  const active = new Map();
  let disposed = false;
  let openLootbox = null;
  lootboxButton.addEventListener('click', event => {
    event.stopPropagation?.();
    if (disposed || lootboxButton.disabled || !openLootbox) return;
    const open = openLootbox;
    openLootbox = null; lootboxButton.disabled = true;
    open();
  });
  let lastPrimary = '0', lastSecondary = '', settled = false;
  const writeText = (node, text) => {
    if (node.textContent === text) return;
    // Keep the text node during a count-up. Replacing it on every frame makes
    // ancestor :has() rules restyle the entire reveal, including covered cards.
    const child = node.firstChild;
    if (child?.nodeType === 3 && !child.nextSibling) child.nodeValue = text;
    else node.textContent = text;
  };
  const parse = text => /^([^\d]*)([\d,]+(?:\.\d+)?)(.*)$/.exec(String(text));
  const stop = node => {
    const animation = active.get(node);
    if (animation) { animation.cancelled = true; view.cancelAnimationFrame?.(animation.id); }
    active.delete(node);
  };
  function count(node, text, previous, duration) {
    stop(node);
    const to = parse(text), from = parse(previous);
    const target = to ? Number(to[2].replaceAll(',', '')) : NaN;
    const start = from ? Number(from[2].replaceAll(',', '')) : 0;
    if (!to || !Number.isFinite(target) || !Number.isFinite(start) || !duration
      || !view.requestAnimationFrame || view.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
      writeText(node, text); return;
    }
    const decimals = Math.max((to[2].split('.')[1] || '').length, (from?.[2].split('.')[1] || '').length);
    const format = new Intl.NumberFormat('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
    const animation = { cancelled: false, id: null, startTime: null };
    active.set(node, animation);
    const step = now => {
      if (disposed || animation.cancelled) return;
      animation.startTime ??= now;
      const progress = Math.min(1, (now - animation.startTime) / duration);
      const number = start + (target - start) * (1 - (1 - progress) ** 3);
      writeText(node, to[1] + format.format(number) + to[3]);
      if (progress < 1) animation.id = view.requestAnimationFrame(step);
      else { writeText(node, text); active.delete(node); }
    };
    animation.id = view.requestAnimationFrame(step);
  }
  return {
    element, coinSlot,
    update(text, { secondaryText = '', caption = 'WINNINGS', detail = '', duration = 420 } = {}) {
      if (disposed || settled) return;
      writeText(label, caption); writeText(status, detail);
      if (text !== lastPrimary) count(primary, text, primary.textContent, duration);
      if (secondaryText !== lastSecondary) count(secondary, secondaryText, secondary.textContent, duration);
      lastPrimary = text; lastSecondary = secondaryText;
      writeText(announcement, [text, secondaryText, detail].filter(Boolean).join('. '));
    },
    showCoin(node, detail) {
      if (disposed) return;
      openLootbox = null; lootboxButton.hidden = true; lootboxButton.disabled = true;
      coinSlot.hidden = false; rewardLabel.hidden = false;
      rewardLabel.textContent = 'COIN FLIP';
      coinSlot.textContent = ''; coinSlot.appendChild(node);
      element.classList.add('has-coin'); status.textContent = detail;
    },
    clearCoin() {
      if (disposed) return;
      coinSlot.textContent = ''; coinSlot.appendChild(placeholder);
      rewardLabel.textContent = 'REWARD';
      element.classList.remove('has-coin');
    },
    showLootbox({ artSrc, amountText, count = 1, complete = false, onOpen = null }) {
      if (disposed) return;
      coinSlot.hidden = true; rewardLabel.hidden = true; lootboxButton.hidden = false;
      element.classList.remove('has-coin');
      if (lootboxArt.getAttribute('src') !== artSrc) lootboxArt.src = artSrc;
      const name = count > 1 ? `${count} LUCKBOXES` : 'LUCKBOX';
      writeText(lootboxLabel, onOpen ? (count > 1 ? `OPEN ${count} BOXES` : 'OPEN LUCKBOX') : name);
      openLootbox = onOpen;
      lootboxButton.disabled = !onOpen;
      lootboxButton.setAttribute('aria-label', `${onOpen ? 'Open' : 'Earned'} ${name.toLowerCase()}: ${amountText}${complete ? '' : '. Finish revealing your cards to open'}`);
      lootboxButton.title = onOpen ? 'Open your earned rewards'
        : complete ? 'Earned luckbox' : 'Finish revealing your cards to open';
    },
    setStatus(text) { status.textContent = text; },
    finish(receipt, { duration = 600 } = {}) {
      settled = true;
      const previous = [primary.textContent, secondary.textContent];
      for (const node of active.keys()) stop(node);
      amount.textContent = ''; amount.appendChild(receipt);
      const lines = [...receipt.children].filter(node => parse(node.textContent));
      if (!lines.length) lines.push(receipt);
      lines.forEach((node, i) => count(node, node.textContent, previous[i] || '0', duration));
      label.textContent = 'FINAL PAYOUT';
      announcement.textContent = receipt.textContent;
    },
    dispose() {
      disposed = true;
      openLootbox = null; lootboxButton.disabled = true;
      for (const node of active.keys()) stop(node);
    },
  };
}
